  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Modelo de usuário\nmodel User {\n  id       String @id @default(cuid())\n  email    String @unique\n  password String\n  role     String @default(\"USER\")\n  status   String @default(\"PENDING_VERIFICATION\")\n\n  // Informações pessoais\n  firstName String\n  lastName  String\n  phone     String?\n  avatar    String?\n  birthDate DateTime?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Verificação de email\n  emailVerified          Boolean @default(false)\n  emailVerificationToken String?\n\n  // Reset de senha\n  passwordResetToken   String?\n  passwordResetExpires DateTime?\n\n  // Relacionamentos\n  profile       UserProfile?\n  refreshTokens RefreshToken[]\n  bookings      Booking[]\n  reviews       Review[]\n\n  @@map(\"users\")\n}\n\n// Perfil detalhado do usuário\nmodel UserProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Informações adicionais\n  cpf     String?\n  address String?\n  city    String?\n  state   String?\n  zipCode String?\n  country String? @default(\"Brasil\")\n\n  // Preferências\n  language String? @default(\"pt-BR\")\n  timezone String? @default(\"America/Sao_Paulo\")\n\n  // Configurações de notificação\n  emailNotifications Boolean @default(true)\n  smsNotifications   Boolean @default(false)\n  pushNotifications  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"user_profiles\")\n}\n\n// Tokens de refresh JWT\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@map(\"refresh_tokens\")\n}\n\n// Modelo de profissional\nmodel Professional {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  // Informações profissionais\n  type           String\n  specialization String\n  license        String @unique\n  experience     Int // anos de experiência\n\n  // Localização\n  address   String\n  city      String\n  state     String\n  zipCode   String\n  latitude  Float?\n  longitude Float?\n\n  // Configurações\n  isActive        Boolean @default(true)\n  isVerified      Boolean @default(false)\n  consultationFee Float?\n\n  // Horários de trabalho (JSON)\n  workingHours String?\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relacionamentos\n  services Service[]\n  bookings Booking[]\n  reviews  Review[]\n\n  @@map(\"professionals\")\n}\n\n// Serviços oferecidos pelos profissionais\nmodel Service {\n  id             String       @id @default(cuid())\n  professionalId String\n  professional   Professional @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  name        String\n  description String?\n  price       Float\n  duration    Int // em minutos\n  isActive    Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relacionamentos\n  bookings Booking[]\n\n  @@map(\"services\")\n}\n\n// Agendamentos\nmodel Booking {\n  id             String       @id @default(cuid())\n  userId         String\n  user           User         @relation(fields: [userId], references: [id])\n  professionalId String\n  professional   Professional @relation(fields: [professionalId], references: [id])\n  serviceId      String\n  service        Service      @relation(fields: [serviceId], references: [id])\n\n  // Detalhes do agendamento\n  scheduledAt DateTime\n  status      String   @default(\"PENDING\")\n  notes       String?\n\n  // Valores\n  price         Float\n  paymentStatus String? @default(\"PENDING\")\n\n  // Timestamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relacionamentos\n  review Review?\n\n  @@map(\"bookings\")\n}\n\n// Avaliações\nmodel Review {\n  id             String       @id @default(cuid())\n  bookingId      String       @unique\n  booking        Booking      @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n  userId         String\n  user           User         @relation(fields: [userId], references: [id])\n  professionalId String\n  professional   Professional @relation(fields: [professionalId], references: [id])\n\n  rating  Int // 1-5\n  comment String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"reviews\")\n}\n\n// Logs de auditoria\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  action    String\n  resource  String\n  details   String?\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@map(\"audit_logs\")\n}\n",
